    "answer": 0,
    "explain": "epidemic curve คือกราฟจำนวนผู้ป่วยตามวันเริ่มป่วย ใช้บรรยายการระบาดตามเวลา รูปแบบของกราฟบอกชนิดของการระบาด ว่าเป็นการระบาดจากแหล่งโรคร่วม (common source แบบ point, intermittent หรือ continuous) หรือการระบาดที่แพร่ต่อกันไป (propagated) ซึ่งช่วยตั้งสมมติฐานเรื่องแหล่งโรคและวิธีแพร่ และใช้ประมาณระยะฟักตัวได้ การเฝ้าระวังโรคอย่างเป็นระบบคือการเก็บ วิเคราะห์ และแปลผลข้อมูลอย่างต่อเนื่อง การค้นหาผู้ป่วยเพิ่มทำผ่านนิยามผู้ป่วยและการค้นหาเชิงรุก และการเตรียมอุปกรณ์เก็บตัวอย่างเป็นงานในขั้นเตรียมการก่อนลงพื้นที่ ไม่ใช่สิ่งที่กราฟนี้ให้",
