    "type": "mcq",
    "q": "จากการศึกษาหนึ่งพบว่า ยา A มีผลต่อการหายของโรคพยาธิเม็ดเลือดในสุนัข อย่างมีนัยสำคัญทางสถิติที่ P-value < 0.05 หมายความว่าอย่างไร",
    "options": [
      "ถ้าทำการศึกษาซ้ำ 100 ครั้ง จะมีการศึกษามากกว่า 95 ครั้งที่ยา A มีผลต่อการหายของโรคจริง ๆ",
      "ถ้าทำการศึกษาซ้ำ 100 ครั้ง จะมีการศึกษาน้อยกว่า 95 ครั้งที่ยา A มีผลต่อการหายของโรคจริง ๆ",
      "ถ้าทำการศึกษาซ้ำ 100 ครั้ง จะมีการศึกษามากกว่า 5 ครั้งที่ยา A มีผลต่อการหายของโรคโดยบังเอิญ",
      "ถ้าทำการศึกษาซ้ำ 100 ครั้ง จะมีการศึกษาน้อยกว่า 5 ครั้งที่ยา A มีผลต่อการหายของโรคจริง ๆ"
    ],
    "answer": 0,
    "explain": "P-value ช่วยตัดสินว่าผลที่เห็นน่าจะเป็นผลจริงหรือเกิดจากความบังเอิญ ค่า P < 0.05 หมายความว่าถ้ายา A ไม่มีผลจริง (H0 เป็นจริง) โอกาสที่จะได้ผลต่างขนาดนี้จากความบังเอิญมีน้อยกว่า 5 ใน 100 จึงปฏิเสธ H0 ได้ ตัวเลือกที่ถูกเล่าความหมายนี้แบบย่อด้วยภาพการทำซ้ำ 100 ครั้ง คือผลที่เห็นน่าจะเป็นผลจริงมากกว่าเกิดจากความบังเอิญ ทั้งนี้ค่า P คิดโดยสมมติว่ายาไม่มีผล จึงไม่ได้บอกโดยตรงว่าการศึกษาซ้ำจะพบผลจริงกี่ครั้ง ข้อความว่ามากกว่า 5 ครั้งเกิดโดยบังเอิญกลับทิศกับ P < 0.05 ส่วนข้อความว่ามีผลจริงน้อยกว่า 95 ครั้ง หรือน้อยกว่า 5 ครั้ง ขัดกับการที่ผลมีนัยสำคัญ",
    "source": "Data analysis & applied statistic for epidemiology_TC หน้า 77-79; Sample size determination_TC หน้า 23",
