    "year": 5,
    "type": "mcq",
    "q": "ข้อใดเป็นการศึกษาโดยการตรวจวัดผลลัพธ์โดยไม่ได้เปลี่ยนแปลงปัจจัยใด ๆ กับประชากรสัตว์ที่ทำการศึกษา",
    "options": [
      "การทดลองทางคลินิก (Clinical trials)",
      "การศึกษาเชิงสังเกต (Observational study)",
      "การศึกษาไปข้างหน้า (Cohort study)",
      "การศึกษาจากเหตุไปหาผล (Prospective study)"
    ],
    "answer": 1,
    "explain": "การศึกษาเชิงทดลอง (experimental) ให้ผู้วิจัยกำหนด exposure หรือสิ่งแทรกแซงให้กลุ่มสัตว์ เช่น การทดลองทางคลินิก ส่วนการศึกษาเชิงสังเกต (observational) ผู้วิจัยเพียงสังเกตและวัดผลจาก exposure ที่เกิดขึ้นเองตามจริงโดยไม่เปลี่ยนแปลงปัจจัยใด ๆ ซึ่งตรงกับนิยามที่ถาม cohort study ทั้งแบบไปข้างหน้า (prospective) และย้อนหลัง ก็ไม่เปลี่ยนแปลงปัจจัยเช่นกัน แต่เป็นรูปแบบย่อยของการศึกษาเชิงสังเกต ชื่อที่ตรงกับนิยามนี้ทั้งหมดจึงเป็น observational study",
