    "explain": "แบบสอบถามที่ดีถามเฉพาะสิ่งที่ต้องใช้ตอบคำถามวิจัย ใช้คำถามปลายปิดที่ทุกคนตอบในรูปแบบเดียวกันจนนำมาเปรียบเทียบและวิเคราะห์ได้ เก็บข้อมูลเป็นตัวเลขที่แน่ชัด และเรียงลำดับคำถามอย่างเหมาะสม คำถามปลายเปิดทำให้แต่ละคนตอบสั้นยาวต่างกันจนเปรียบเทียบกันไม่ได้ ซึ่งเป็นที่มาของอคติจากข้อมูล (information bias) การใส่คำถามให้มากที่สุดเพิ่มภาระผู้ตอบ และการไม่ตอบกลับหรือตอบไม่ครบลดจำนวนตัวอย่างที่ใช้ได้จริง จึงไม่ใช่ลักษณะที่ดี",
