    "type": "mcq",
    "q": "ความสัมพันธ์ (Association) ต่างจากสาเหตุ (Causation) อย่างไร",
    "options": [
      "ความสัมพันธ์ระหว่างสองตัวแปรจำเป็นต้องเป็นปัจจัยเสี่ยงกับผลลัพธ์",
      "ความสัมพันธ์เป็นการศึกษาระหว่างผลลัพธ์กับปัจจัยเสี่ยงเท่านั้น",
      "สาเหตุอาจเป็นตัวแปรทั่วไปที่ไม่ได้มีความเกี่ยวข้องโดยตรงต่อการเกิดผลลัพธ์",
      "สาเหตุเป็นการศึกษาความสัมพันธ์ระหว่างปัจจัยเสี่ยงและผลลัพธ์ที่เกิดจากปัจจัยเสี่ยงนั้น"
    ],
    "answer": 3,
    "explain": "ความสัมพันธ์ (association) คือการที่สองตัวแปรเกิดร่วมกันบ่อยกว่าที่คาดจากความบังเอิญ ตัวแปรคู่นั้นเป็นอะไรก็ได้ ไม่จำเป็นต้องเป็นปัจจัยเสี่ยงกับผลลัพธ์ และการพบความสัมพันธ์ไม่ได้แปลว่าตัวหนึ่งเป็นเหตุของอีกตัว สาเหตุ (causation) คือเหตุการณ์ สภาวะ หรือคุณลักษณะที่มีบทบาทสำคัญและทำให้การเกิดผลลัพธ์เปลี่ยนไปอย่างคาดเดาได้ จึงเป็นความสัมพันธ์ระหว่างปัจจัยกับผลลัพธ์ที่ปัจจัยนั้นทำให้เกิด สาเหตุจึงไม่ใช่ตัวแปรทั่วไปที่ไม่เกี่ยวข้องโดยตรงกับการเกิดผลลัพธ์",
