    "say": "ข้อมูล 2X2 ต่อไปนี้เป็นผลของการศึกษาจากผลไปหาเหตุ เพื่อวิเคราะห์หาปัจจัยเสี่ยงจากการฉีดยาคุมกำเนิดในสุนัขที่มีปัญหามดลูกอักเสบ โดยศึกษาในสุนัข 33 ตัวที่ฉีดและไม่ฉีดยาคุมกำเนิด ดังนี้ ฉีดยาคุมกำเนิด: มดลูกอักเสบ 10 ปกติ 6 รวม 16; ไม่ฉีดยาคุมกำเนิด: มดลูกอักเสบ 5 ปกติ 12 รวม 17; รวม: มดลูกอักเสบ 15 ปกติ 18 รวม 33 ค่า odds ratio (OR) จากข้อมูลนี้สามารถแปลความหมายได้ว่าอย่างไร",
    "passage": "ข้อมูล 2X2 ต่อไปนี้เป็นผลของการศึกษาจากผลไปหาเหตุ เพื่อวิเคราะห์หาปัจจัยเสี่ยงจากการฉีดยาคุมกำเนิดในสุนัขที่มีปัญหามดลูกอักเสบ โดยศึกษาในสุนัข 33 ตัวที่ฉีดและไม่ฉีดยาคุมกำเนิด\n\n| | มดลูกอักเสบ | ปกติ | รวม |\n|---|---|---|---|\n| ฉีดยาคุมกำเนิด | 10 | 6 | 16 |\n| ไม่ฉีดยาคุมกำเนิด | 5 | 12 | 17 |\n| รวม | 15 | 18 | 33 |",
    "passage_title": "การฉีดยาคุมกำเนิดกับมดลูกอักเสบในสุนัข 33 ตัว",
    "options": [
      "สุนัขที่ได้รับการฉีดยาคุมกำเนิดมีโอกาสเป็นโรคมดลูกอักเสบ น้อยกว่าสุนัขที่ไม่ได้รับการฉีดยา",
      "สุนัขที่ไม่ได้รับการฉีดยาคุมกำเนิดมีโอกาสเป็นโรคมดลูกอักเสบ มากกว่าสุนัขที่ได้รับการฉีดยาคุม",
      "สุนัขที่เป็นโรคมดลูกอักเสบมีโอกาสได้รับการฉีดยาคุมกำเนิดมาก่อน น้อยกว่าสุนัขที่ไม่เป็นมดลูกอักเสบ",
      "สุนัขที่เป็นโรคมดลูกอักเสบมีโอกาสได้รับการฉีดยาคุมกำเนิดมาก่อน มากกว่าสุนัขที่ไม่เป็นมดลูกอักเสบ"
    ],
    "answer": 3,
    "explain": "**หลัก** การศึกษาจากผลไปหาเหตุ (case-control) เลือกตัวอย่างจากสถานะโรคแล้วมองย้อนหาการสัมผัส OR จึงเทียบ odds ของการเคยได้รับยาคุมกำเนิดในสุนัขที่เป็นมดลูกอักเสบกับสุนัขปกติ\n**แทนค่า** OR = (10 x 12)/(6 x 5) = 120/30 = 4\n**แปลผล** ค่า 4 ที่มากกว่า 1 แปลว่าสุนัขที่เป็นมดลูกอักเสบมีโอกาสเคยได้รับยาคุมกำเนิดมาก่อนมากกว่าสุนัขที่ไม่เป็น\n\n❌ ทำไมข้ออื่นผิด\n— \"สุนัขที่เป็นโรคมดลูกอักเสบมีโอกาสได้รับการฉีดยาคุมกำเนิดมาก่อน น้อยกว่าสุนัขที่ไม่เป็นมดลูกอักเสบ\" แปลกลับทิศ\n— ข้อความว่าสุนัขที่ฉีดยามีโอกาสเป็นโรคน้อยกว่า หรือสุนัขที่ไม่ฉีดมีโอกาสเป็นโรคมากกว่า ก็กลับทิศเช่นกัน และยังอ่านเป็นความเสี่ยงของการเกิดโรค ซึ่งการเลือกตัวอย่างตามสถานะโรคไม่ได้ให้ค่าความเสี่ยงที่แท้จริง",
    "explainSay": "OR = (10 x 12)/(6 x 5) = 120/30 = 4 การศึกษาจากผลไปหาเหตุ (case-control) เลือกตัวอย่างจากสถานะโรคแล้วมองย้อนหาการสัมผัส OR จึงเทียบ odds ของการเคยได้รับยาคุมกำเนิดในสุนัขที่เป็นมดลูกอักเสบกับสุนัขปกติ ค่า 4 ที่มากกว่า 1 แปลว่าสุนัขที่เป็นมดลูกอักเสบมีโอกาสเคยได้รับยาคุมกำเนิดมาก่อนมากกว่าสุนัขที่ไม่เป็น ข้อความที่บอกว่าน้อยกว่าแปลกลับทิศ ส่วนข้อความว่าสุนัขที่ฉีดยามีโอกาสเป็นโรคน้อยกว่า หรือสุนัขที่ไม่ฉีดมีโอกาสเป็นโรคมากกว่า ก็กลับทิศเช่นกัน และยังอ่านเป็นความเสี่ยงของการเกิดโรค ซึ่งการเลือกตัวอย่างตามสถานะโรคไม่ได้ให้ค่าความเสี่ยงที่แท้จริง",
