    "id": 213521,
    "subject": "epidemiology",
    "topic": "epidem-disease-frequency",
    "year": 5,
    "type": "mcq",
    "examScope": "final",
    "q": "In an outbreak of gastroenteritis and vomiting among participants of one party, 90 persons ate hamburger, 20 of them developed gastroenteritis and vomiting, and 99 persons ate chicken salad, 30 of them developed the symptoms. The total number of participants were 189. Please calculate attack rate of this outbreak among persons who ate chicken salad.",
    "options": [
      "(30/99) × 100",
      "(30/69) × 100",
      "(30/189) × 100",
      "(50/189) × 100"
    ],
    "answer": 0,
    "explain": "**สูตร** attack rate คืออุบัติการณ์ในช่วงที่มีการระบาด = จำนวนผู้ป่วยรายใหม่ ÷ จำนวนประชากรเสี่ยงเมื่อเริ่มต้น x 100\n**ตัวหาร** ประชากรเสี่ยงของกลุ่มที่กินสลัดไก่คือทุกคนที่กินสลัดไก่ 99 คน ซึ่งรวมคนที่ป่วยด้วย\n**แทนค่า** (30/99) x 100 = 30.3%\n\n❌ ทำไมข้ออื่นผิด\n— (30/69) × 100 ตัดคนที่ป่วยออกจากตัวหาร\n— (30/189) × 100 หารด้วยผู้ร่วมงานทั้งหมด ซึ่งรวมคนที่ไม่ได้กินสลัดไก่\n— (50/189) × 100 เป็น attack rate รวมของทั้งงานจากผู้ป่วย 20 + 30 คน ไม่ใช่เฉพาะกลุ่มที่กินสลัดไก่",
    "explainSay": "attack rate คืออุบัติการณ์ในช่วงที่มีการระบาด = จำนวนผู้ป่วยรายใหม่ ÷ จำนวนประชากรเสี่ยงเมื่อเริ่มต้น x 100 ประชากรเสี่ยงของกลุ่มที่กินสลัดไก่คือทุกคนที่กินสลัดไก่ 99 คน ซึ่งรวมคนที่ป่วยด้วย จึงได้ (30/99) x 100 = 30.3% การหารด้วย 69 ตัดคนที่ป่วยออกจากตัวหาร การหารด้วย 189 ใช้ผู้ร่วมงานทั้งหมดซึ่งรวมคนที่ไม่ได้กินสลัดไก่ และ (50/189) x 100 เป็น attack rate รวมของทั้งงานจากผู้ป่วย 20 + 30 คน ไม่ใช่เฉพาะกลุ่มที่กินสลัดไก่",
