    "explain": "การสอบสวนการระบาดทำเพื่อปกป้องสุขภาพคนและสัตว์ ด้วยการหาแหล่งโรคและหยุดการแพร่ที่กำลังเกิดอยู่ แล้วดำเนินมาตรการควบคุมและป้องกัน เป้าหมายหลักจึงเป็นการควบคุมการระบาดครั้งนั้น การยืนยันการวินิจฉัย (ขั้นที่ 3) และการใช้ระบาดวิทยาเชิงวิเคราะห์ทดสอบสมมติฐาน (ขั้นที่ 7) เป็นขั้นตอนที่พาไปสู่เป้าหมาย ไม่ใช่ตัวเป้าหมาย ส่วนการกำจัดโรค (eradication) คือการทำให้โรคหรือตัวก่อโรคหมดไปจากพื้นที่ ซึ่งเป็นเป้าหมายของโครงการระยะยาว ไม่ใช่ของการสอบสวนการระบาดหนึ่งครั้ง",
