    "id": 213525,
    "subject": "epidemiology",
    "topic": "epidem-disease-frequency",
    "year": 5,
    "type": "mcq",
    "examScope": "final",
    "q": "ในจังหวัดหนึ่งที่เป็นเกาะแห่งหนึ่ง สุนัขทุกตัวในจังหวัดนี้มีการลงทะเบียนกับทางหน่วยงานราชการและไม่มีสุนัขที่ไม่มีเจ้าของเลย เมื่อปี 2560 มีสุนัขที่ลงทะเบียนทั้งสิ้น 456 ตัว พบว่ามีสุนัขที่เป็นโรคพิษสุนัขบ้าในปี 2560 ทั้งหมด 5 ตัว ให้คำนวณหา case fatality rate ของโรคพิษสุนัขบ้าในสุนัขในจังหวัดนี้",
    "options": [
      "0.5%",
      "1.1%",
      "95%",
      "100%"
    ],
    "answer": 3,
    "explain": "**สูตร** case fatality rate (อัตราป่วยตาย) = จำนวนที่ตายด้วยโรค ÷ จำนวนที่ป่วยด้วยโรคนั้น x 100\n**ตัวหาร** สุนัขที่ป่วยเป็นโรคพิษสุนัขบ้า 5 ตัว ไม่ใช่สุนัขที่ลงทะเบียน 456 ตัว\n**แทนค่า** สุนัขที่ป่วยเป็นโรคพิษสุนัขบ้าตายทุกตัว ได้ 5/5 x 100 = 100%\n\n**ข้อควรระวัง**\n— ค่า 1.1% มาจาก 5/456 ซึ่งเป็นสัดส่วนสุนัขที่ป่วยในประชากรทั้งหมด (แนวเดียวกับ morbidity rate) ไม่ใช่อัตราป่วยตาย",
    "explainSay": "case fatality rate (อัตราป่วยตาย) = จำนวนที่ตายด้วยโรค ÷ จำนวนที่ป่วยด้วยโรคนั้น x 100 ตัวหารจึงเป็นสุนัขที่ป่วยเป็นโรคพิษสุนัขบ้า 5 ตัว ไม่ใช่สุนัขที่ลงทะเบียน 456 ตัว สุนัขที่ป่วยเป็นโรคพิษสุนัขบ้าตายทุกตัว ได้ 5/5 x 100 = 100% ค่า 1.1% มาจาก 5/456 ซึ่งเป็นสัดส่วนสุนัขที่ป่วยในประชากรทั้งหมด (แนวเดียวกับ morbidity rate) ไม่ใช่อัตราป่วยตาย",
    "source": "Measurement of disease frequency- measurement of association- diagnostic test หน้า 29, 31-32; WHO Rabies fact sheet (17 ก.ย. 2569): เมื่อมีอาการทางคลินิกแล้วโรคพิษสุนัขบ้าทำให้ตายทุกราย",
    "verified": "บันทึกข้อสอบปลายภาคแบบออนไลน์ของ Vet 81 ฉบับตรวจแล้ว (ได้ 18/25 มีเครื่องหมายถูกผิดรายข้อ) ในชุดไฟล์ Epidem final ที่ติดดาวของ Vet 84 หน้า 6 ข้อ 11; บันทึกหลังสอบปลายภาคของ Vet 82 (เขียนมือ) ในชุดไฟล์ Epidem final ของ Vet 84 หน้า 2 ส่วนที่ 2 บรรทัด \"case fatality rate = ? ตอบ 100%\" และสำเนาหน้าเดียวกันในชุดไฟล์ Epidem final ที่ติดดาวของ Vet 84 หน้า 2; เครื่องหมายสีชมพูของ Vet 83 ที่ข้อ 11 ของบันทึก Vet 81 หน้า 6 (ข้อเดียวกันอยู่บนข้อสอบของ Vet 83)",
