    "id": 213526,
    "subject": "epidemiology",
    "topic": "epidem-dx-screening",
    "year": 5,
    "type": "mcq",
    "examScope": "final",
    "q": "ในการนำเครื่องมือวินิจฉัยโรคพิษสุนัขบ้าเครื่องมือหนึ่งไปใช้วินิจฉัยโรคพิษสุนัขบ้าในสุนัขในเขตกรุงเทพมหานคร ผู้วิจัยพบว่าเมื่อคำนวณค่า positive predictive value (PPV) ได้เท่ากับ 34% หมายความว่าอย่างไร",
    "options": [
      "หากมีสุนัขที่เป็นโรค 100 ตัว เครื่องมือนี้จะให้ผลบวก 34 ตัว",
      "หากมีสุนัขที่เป็นโรค 100 ตัว เครื่องมือนี้จะให้ผลลบ 66 ตัว",
      "หากสุนัขที่ให้ผลบวกกับเครื่องมือนี้ 100 ตัว จะเป็นโรคพิษสุนัขบ้า 34 ตัว",
      "หากสุนัขที่ให้ผลบวกกับเครื่องมือนี้ 100 ตัว จะเป็นโรคพิษสุนัขบ้า 66 ตัว"
    ],
    "answer": 2,
    "explain": "PPV คือโอกาสที่สัตว์ที่ให้ผลบวกจะเป็นโรคจริง P(D+|T+) = ผลบวกจริง ÷ ผลบวกทั้งหมด PPV 34% จึงแปลว่าในสุนัข 100 ตัวที่เครื่องมือให้ผลบวก เป็นโรคพิษสุนัขบ้าจริง 34 ตัว อีก 66 ตัวเป็นผลบวกลวง การเริ่มจากสุนัขที่เป็นโรค 100 ตัวแล้วนับว่าได้ผลบวกหรือผลลบกี่ตัว เป็นความหมายของ sensitivity และผลลบลวง ไม่ใช่ PPV และ PPV ขึ้นกับความชุกของโรคในพื้นที่ที่นำเครื่องมือไปใช้ ความชุกยิ่งต่ำ PPV ยิ่งต่ำ",
