    "q": "นักวิจัยต้องการศึกษาปัจจัยที่มีความสัมพันธ์กับการไม่พาสุนัขไปฉีดวัคซีนป้องกันโรคพิษสุนัขบ้า โดยอาศัยรูปแบบของการใช้แบบสอบถามโดยเข้าไปทำการศึกษาในจังหวัดนครปฐม ในการศึกษาครั้งนี้ควรออกแบบการศึกษาเป็นแบบใด",
    "options": [
      "Cross-sectional study",
      "Case-control study",
      "Retrospective cohort study",
      "Prospective cohort study"
    ],
    "answer": 0,
    "explain": "การเข้าไปเก็บแบบสอบถามจากเจ้าของสุนัขในจังหวัดครั้งเดียว ได้ทั้งข้อมูลปัจจัยต่าง ๆ และผลลัพธ์ (การพาหรือไม่พาสุนัขไปฉีดวัคซีน) ในเวลาเดียวกัน เป็นโครงสร้างของ cross-sectional study ซึ่งศึกษาหลาย exposure ได้พร้อมกัน ทำได้เร็วและประหยัด case-control study ต้องเลือกตัวอย่างจากสถานะของผลลัพธ์ก่อนแล้วย้อนหาปัจจัย ส่วน retrospective และ prospective cohort ต้องเริ่มจากกลุ่มที่กำหนดด้วย exposure แล้วติดตามผลลัพธ์ตามเวลา จากข้อมูลย้อนหลังหรือไปข้างหน้า ซึ่งการสำรวจด้วยแบบสอบถามครั้งเดียวไม่ได้ทำ",
