    "explain": "อุบัติการณ์คือผู้ป่วยรายใหม่ ยาและเวชภัณฑ์รักษาใช้กับสัตว์ที่ป่วยแล้ว จึงลดความชุกด้วยการทำให้ระยะป่วยสั้นลง (P = IR x D) แต่ลดการเกิดผู้ป่วยรายใหม่ได้เพียงทางอ้อม จากการที่สัตว์ป่วยแพร่เชื้อได้สั้นลง และการป้องกันหลังสัตว์แสดงอาการแล้วได้ผลน้อยกว่าการป้องกันในระดับก่อนหน้า วัคซีนที่มีประสิทธิภาพป้องกันไม่ให้สัตว์ที่ยังไม่ป่วยติดโรค ชุดตรวจที่ถูกต้องแม่นยำทำให้พบสัตว์ติดเชื้อเร็วและจัดการได้ก่อนแพร่ต่อ และการอบรมเกษตรกรและเจ้าหน้าที่ช่วยให้ป้องกันและแจ้งโรคได้เร็ว ทั้งสามอย่างลดผู้ป่วยรายใหม่ได้มากกว่ายารักษา",
