    "id": 213535,
    "subject": "epidemiology",
    "topic": "epidem-dx-screening",
    "year": 5,
    "type": "mcq",
    "examScope": "final",
    "q": "ถ้าจะนำผลการศึกษานี้ไปใช้ ข้อใดกล่าวไม่ถูกต้อง",
    "options": [
      "สุนัขมีความสามารถในการคัดกรองคนที่ไม่ป่วยได้ดีมาก",
      "สุนัขมีความสามารถในการคัดกรองคนที่ป่วยได้ดีมาก",
      "สุนัขมีความสามารถในการคัดกรองคนที่เข้ามาตรวจคัดกรองได้ดีมาก",
      "ระดับความชุกจริงของคนที่เข้ามาตรวจคัดกรองต่ำมาก"
    ],
    "answer": 1,
    "explain": "สุนัขแยกคนที่ไม่ติดเชื้อได้ดีมาก แต่การคัดกรองคนที่ป่วยไม่ได้ดีมาก\n\n| ค่า | คำนวณ |\n|---|---|\n| ความจำเพาะ | 3246/3272 = 99.2% |\n| NPV | 3246/3249 = 99.9% |\n| จัดกลุ่มถูก | (15 + 3246)/3290 = 99.1% |\n| ความชุกจริง | 18/3290 = 0.55% |\n| ความไว | 15/18 = 83.3% |\n| PPV | 15/41 = 36.6% |\n\nผู้ที่สุนัขให้ผลลบเป็นผู้ไม่ติดเชื้อจริง (NPV) และความชุกจริงตาม RT-PCR ต่ำมาก แต่ความไวพลาดผู้ติดเชื้อ 3 ราย และผู้ที่สุนัขให้ผลบวก 41 คน ติดเชื้อจริงเพียง 15 คน เพราะเมื่อความชุกต่ำ PPV ก็ต่ำตาม ข้อความว่าสุนัขคัดกรองคนที่ป่วยได้ดีมากจึงไม่ถูกต้อง",
    "explainSay": "สุนัขแยกคนที่ไม่ติดเชื้อได้ดีมาก ความจำเพาะ 3246/3272 = 99.2% และผู้ที่สุนัขให้ผลลบเป็นผู้ไม่ติดเชื้อจริง 3246/3249 = 99.9% (NPV) ภาพรวมจัดกลุ่มถูก (15 + 3246)/3290 = 99.1% และความชุกจริงตาม RT-PCR คือ 18/3290 = 0.55% ซึ่งต่ำมาก แต่การคัดกรองคนที่ป่วยไม่ได้ดีมาก ความไว 15/18 = 83.3% พลาดผู้ติดเชื้อ 3 ราย และผู้ที่สุนัขให้ผลบวก 41 คน ติดเชื้อจริงเพียง 15 คน (PPV 36.6%) เพราะเมื่อความชุกต่ำ PPV ก็ต่ำตาม ข้อความว่าสุนัขคัดกรองคนที่ป่วยได้ดีมากจึงไม่ถูกต้อง",
    "source": "Measurement of disease frequency- measurement of association- diagnostic test หน้า 83, 85, 88, 92-94",
