    "model_answer": "ดูจาก case fatality rate (อัตราป่วยตาย) = จำนวนสัตว์ที่ตายด้วยโรคหนึ่ง ÷ จำนวนสัตว์ที่ป่วยด้วยโรคนั้น x 100 ค่านี้บอกว่าในบรรดาสัตว์ที่ป่วย มีสัดส่วนเท่าใดที่ตายจากโรค",
    "explain": "ตัวหารของอัตราป่วยตายคือสัตว์ที่ป่วยด้วยโรคนั้น จึงวัดความรุนแรงของโรคในผู้ป่วยโดยตรง ต่างจาก mortality rate (จำนวนที่ตาย ÷ ประชากรที่กำหนด) และ morbidity rate (จำนวนที่ป่วย ÷ ประชากรที่กำหนด) ซึ่งตัวหารเป็นประชากรทั้งหมด\n\nเช่น ฟาร์มไก่ 1,000 ตัว ป่วย 500 ตัว ตาย 250 ตัว\n\n| ค่า | คำนวณ |\n|---|---|\n| case fatality rate | 250/500 = 50% |\n| mortality rate | 250/1,000 = 25% |\n| morbidity rate | 500/1,000 = 50% |",
    "explainSay": "ตัวหารของอัตราป่วยตายคือสัตว์ที่ป่วยด้วยโรคนั้น จึงวัดความรุนแรงของโรคในผู้ป่วยโดยตรง ต่างจาก mortality rate (จำนวนที่ตาย ÷ ประชากรที่กำหนด) และ morbidity rate (จำนวนที่ป่วย ÷ ประชากรที่กำหนด) ซึ่งตัวหารเป็นประชากรทั้งหมด เช่น ฟาร์มไก่ 1,000 ตัว ป่วย 500 ตัว ตาย 250 ตัว case fatality rate = 250/500 = 50% ส่วน mortality rate = 250/1,000 = 25% และ morbidity rate = 500/1,000 = 50%",
