    "id": 213539,
    "subject": "epidemiology",
    "topic": "epidem-causation",
    "year": 5,
    "type": "short",
    "examScope": "final",
    "q": "ความสัมพันธ์ของความเสี่ยงในกลุ่มที่ได้ exposure กับกลุ่มที่ไม่ได้ exposure ว่าต่างกันกี่เท่า คือค่าอะไร",
    "keywords": [
      "relative risk",
      "risk ratio",
      "RR",
      "ความเสี่ยงในกลุ่มสัมผัส ÷ ความเสี่ยงในกลุ่มไม่สัมผัส",
      "[a/(a+b)] ÷ [c/(c+d)]",
      "RR = 1 ไม่สัมพันธ์"
    ],
    "model_answer": "คือ relative risk (RR, risk ratio หรือความเสี่ยงสัมพัทธ์) = ความเสี่ยงในกลุ่มที่สัมผัส ÷ ความเสี่ยงในกลุ่มที่ไม่สัมผัส = [a/(a+b)] ÷ [c/(c+d)] RR = 1 คือไม่มีความสัมพันธ์ RR มากกว่า 1 คือการสัมผัสเพิ่มความเสี่ยง (ปัจจัยเสี่ยง) และ RR น้อยกว่า 1 คือลดความเสี่ยง (ปัจจัยป้องกัน)",
    "explain": "odds ratio (OR) เปรียบเทียบ odds (โอกาสเป็นโรค ÷ โอกาสไม่เป็นโรค) ไม่ใช่ความเสี่ยงโดยตรง OR จะใกล้เคียง RR เมื่อโรคพบได้น้อย และเป็นค่าหลักของ case-control study ซึ่งคิดความเสี่ยงที่แท้จริงไม่ได้ ค่าที่ตอบว่าความเสี่ยงของสองกลุ่มต่างกันกี่เท่าจึงเป็น RR เช่น ความเสี่ยงในกลุ่มสัมผัส 120/5,000 และกลุ่มไม่สัมผัส 50/5,000 ได้ RR = 2.4 คือกลุ่มสัมผัสมีความเสี่ยงเป็น 2.4 เท่าของกลุ่มไม่สัมผัส",
