    "model_answer": "เป็นการศึกษาระดับฟาร์ม (farm หรือ herd level) เพราะหน่วยที่นับและวิเคราะห์คือฝูง ข้อมูลแบ่งฟาร์มเป็น positive herds และ negative herds และ prevalence เป็นสัดส่วนของฝูงที่ติดเชื้อ ปัจจัยที่ศึกษา เช่น stall style, bedding material, presence of cats และการนำโคเข้าฝูงหรือใช้ทุ่งหญ้าร่วมกัน ก็เป็นลักษณะการจัดการของฟาร์ม ไม่ใช่ลักษณะของโคแต่ละตัว",
    "explain": "หน่วยของการศึกษา (epidemiological unit) ดูจากสิ่งที่ถูกนับเป็นหนึ่งหน่วยในการวิเคราะห์ ข้อมูลชุดนี้นับจำนวนฝูงที่ติดเชื้อและไม่ติดเชื้อ ค่า prevalence จึงเป็นความชุกระดับฝูง และทุกปัจจัยเป็นการจัดการหรือประวัติของฟาร์ม ถ้าเป็นการศึกษาระดับตัวสัตว์ ข้อมูลจะนับจำนวนโคที่ผลตรวจบวกและลบ และปัจจัยจะเป็นลักษณะของโคแต่ละตัว การกำหนดหน่วยให้ชัดตั้งแต่ขั้นออกแบบสำคัญ เพราะหน่วยเป็นตัวกำหนดวิธีสุ่มตัวอย่าง ขนาดตัวอย่าง และการแปลผล",
