    "q": "จากผลการวิเคราะห์เบื้องต้น ปัจจัยเสี่ยงใดน่าจะเกี่ยวข้องกับการติดเชื้อ Leptospira hardjo มากที่สุด 3 ลำดับแรก โดยตอบคำถาม 3 ลำดับให้ชัดเจน",
    "keywords": [
      "p-value < 0.001",
      "introduction of cows/use of common grazing",
      "Hokkaido",
      "Tohoku",
      "χ²",
      "Fisher's exact test",
      "ระดับนัยสำคัญ 0.05"
    ],
    "model_answer": "ใช้ p-value จากการวิเคราะห์ตัวแปรเดียวเทียบกับระดับนัยสำคัญ 0.05 ปัจจัยที่มี p-value < 0.001 มีสามปัจจัย 1) Introduction of cows/use of common grazing within 5 years (Fisher's exact test, p < 0.001) ฝูงที่ไม่ได้นำโคเข้าและไม่ใช้ทุ่งหญ้าร่วมกันไม่ติดเชื้อเลย (prevalence 0 เทียบกับ 72.0%) 2) Introduced/returned from Hokkaido (χ² = 23.6, p < 0.001) prevalence 89.1% เทียบกับ 34.8% 3) Introduced/returned from Tohoku (χ² = 18.5, p < 0.001) ซึ่งสัมพันธ์ในทิศทางตรงข้าม คือฝูงที่นำโคจาก Tohoku มี prevalence ต่ำกว่า (46.7% เทียบกับ 91.1%) ทั้งสามมี p < 0.001 จึงเรียงตามความชัดของความแตกต่าง ฝูงที่ไม่มีปัจจัยแรกไม่ติดเชื้อเลย และ χ² ของ Hokkaido มากกว่าของ Tohoku ลำดับถัดไปคือ presence of cats (p = 0.005) ส่วนปัจจัยอื่นมี p-value มากกว่า 0.05 จึงไม่มีนัยสำคัญ",
    "explain": "การคัดเลือกปัจจัยจากการวิเคราะห์เบื้องต้นดูที่ p-value ค่าที่น้อยกว่าหรือเท่ากับ 0.05 ถือว่ามีนัยสำคัญ และยิ่งน้อยยิ่งเป็นหลักฐานหนักแน่นว่าความสัมพันธ์ไม่ได้เกิดจากความบังเอิญ สามปัจจัยที่ p < 0.001 จึงเป็นสามลำดับแรก ตามด้วย presence of cats (p = 0.005) ส่วน stall style (0.09) straw (0.08) frequency of vets visits (0.08) และ sawdust (0.19) ไม่มีนัยสำคัญ ความสัมพันธ์ที่มีนัยสำคัญเกิดได้ทั้งสองทิศทาง ฝูงที่นำโคจาก Tohoku และฝูงที่มีแมวมี prevalence ต่ำกว่า จึงสัมพันธ์ในทางลดการติดเชื้อ และผลจากการวิเคราะห์ตัวแปรเดียวยังต้องตรวจตัวกวนต่อด้วยการวิเคราะห์หลายตัวแปร",
    "source": "Data analysis & applied statistic for epidemiology_TC หน้า 78-79, 111 และ 117; Study Design หน้า 35",
