    "passage": "จากผลการศึกษาปัจจัยเสี่ยงที่มีผลต่อการติดเชื้อ Leptospira hardjo ดังนี้\n\nStall style (Fisher's Exact Test, p-value 0.09)\n\n| | Free stall | Free barn | Tie stall |\n|---|---|---|---|\n| Positive herds | 11 | 1 | 55 |\n| Negative herds | 1 | 1 | 34 |\n| Prevalence (%) | 91.7 | 50.0 | 61.8 |\n\nBedding material, Straw (Chi-squared test, χ² = 3.08, df = 1, p-value 0.08)\n\n| | Yes | No |\n|---|---|---|\n| Positive herds | 18 | 48 |\n| Negative herds | 16 | 18 |\n| Prevalence (%) | 52.9 | 75.0 |\n\nBedding material, Sawdust (Chi-squared test, χ² = 1.71, df = 1, p-value 0.19)\n\n| | Yes | No |\n|---|---|---|\n| Positive herds | 9 | 57 |\n| Negative herds | 9 | 25 |\n| Prevalence (%) | 50.0 | 69.5 |\n\nPresence of cats (Chi-squared test, χ² = 7.84, df = 1, p-value 0.005)\n\n| | Yes | No |\n|---|---|---|\n| Positive herds | 14 | 57 |\n| Negative herds | 18 | 20 |\n| Prevalence (%) | 43.8 | 74.0 |\n\nFrequency of vets visits (time/week) (Chi-squared test, χ² = 3.1, df = 1, p-value 0.08)\n\n| | Twice or more | Once or fewer |\n|---|---|---|\n| Positive herds | 28 | 39 |\n| Negative herds | 8 | 28 |\n| Prevalence (%) | 77.8 | 58.2 |\n\nIntroduction of cows/use of common grazing within 5 years (Fisher's Exact Test, p-value < 0.001)\n\n| | Yes | No |\n|---|---|---|\n| Positive herds | 67 | 0 |\n| Negative herds | 26 | 10 |\n| Prevalence (%) | 72.0 | 0 |\n\nIntroduced/returned from Hokkaido (Chi-squared test, χ² = 23.6, df = 1, p-value < 0.001)\n\n| | Yes | No |\n|---|---|---|\n| Positive herds | 57 | 8 |\n| Negative herds | 7 | 15 |\n| Prevalence (%) | 89.1 | 34.8 |\n\nIntroduced/returned from Tohoku (Chi-squared test, χ² = 18.5, df = 1, p-value < 0.001)\n\n| | Yes | No |\n|---|---|---|\n| Positive herds | 14 | 51 |\n| Negative herds | 16 | 5 |\n| Prevalence (%) | 46.7 | 91.1 |",
    "passage_title": "ปัจจัยเสี่ยงการติดเชื้อ Leptospira hardjo ในฟาร์ม"
