    "model_answer": "เลือก cross-sectional study: สุ่มฟาร์มจากประชากรเป้าหมาย ตรวจสถานะการติดเชื้อ Leptospira hardjo ของแต่ละฟาร์ม และเก็บข้อมูลปัจจัยของฟาร์มในช่วงเวลาเดียวกัน แล้วคำนวณ prevalence และ prevalence ratio หรือ odds ratio ของแต่ละปัจจัย เหตุผล 1) การติดเชื้อพบได้บ่อย ฝูงที่ติดเชื้อมีมากกว่าฝูงที่ไม่ติดเชื้อ จึงไม่จำเป็นต้องใช้ case-control ซึ่งเหมาะกับโรคหายาก 2) ต้องการคัดกรองหลายปัจจัยพร้อมกัน 3) ทำได้เร็วและประหยัด ข้อจำกัดคือบอกได้ไม่ชัดว่าปัจจัยเกิดก่อนการติดเชื้อ ถ้าต้องการยืนยันลำดับเวลา เช่น การนำโคเข้าฝูงเกิดก่อนการติดเชื้อ และวัด incidence ได้โดยตรง ควรใช้ cohort study ติดตามฝูงที่ยังไม่ติดเชื้อไปข้างหน้า แต่ใช้เวลาและงบประมาณมากกว่า",
    "explain": "การเลือกแบบการศึกษาเริ่มจากสามคำถาม: เลือกตัวอย่างจากอะไร ต้องรู้ลำดับเวลาก่อนหลังหรือไม่ และโรคพบได้น้อยเพียงใด ข้อมูลชุดนี้มีสถานะการติดเชื้อและปัจจัยของฟาร์มที่เก็บในคราวเดียวและรายงานเป็น prevalence เป็นลักษณะของ cross-sectional study ที่เร็ว ประหยัด และศึกษาหลายปัจจัยได้พร้อมกัน ข้อจำกัดคือลำดับเวลากำกวม Case-control เหมาะเมื่อโรคหายากหรือระยะฟักตัวยาว และวัด incidence โดยตรงไม่ได้ ส่วน cohort สร้างลำดับเวลาจาก exposure ไปสู่ outcome และวัด risk ได้โดยตรง แต่ต้องติดตามฝูงได้และมีต้นทุนสูง แบบอื่นจึงเลือกได้เมื่อเป้าหมายเปลี่ยน โดยให้เหตุผลตามหลักเดียวกัน",
