    "q": "ถ้าจะประเมินว่าปัจจัย presence of cats เป็นปัจจัยเสี่ยงหรือไม่ จะทำการคำนวณค่าใด ให้แสดงวิธีการคำนวณ พร้อมให้คำอธิบายประกอบให้เข้าใจ",
    "keywords": [
      "odds ratio",
      "OR = ad/bc",
      "(14×20)/(18×57)",
      "0.273",
      "OR < 1",
      "protective factor",
      "p = 0.005"
    ],
    "model_answer": "คำนวณ odds ratio (OR) โดยจัดข้อมูลของปัจจัย presence of cats เป็นตาราง 2×2: ฝูงที่มีแมว ติดเชื้อ 14 ไม่ติดเชื้อ 18 ฝูงที่ไม่มีแมว ติดเชื้อ 57 ไม่ติดเชื้อ 20 OR = ad/bc = (14×20)/(18×57) = 0.273 แปลผล: odds ของการติดเชื้อ Leptospira hardjo ในฝูงที่มีแมวเป็น 0.273 เท่าของ odds ในฝูงที่ไม่มีแมว OR น้อยกว่า 1 การมีแมวจึงไม่ใช่ปัจจัยเสี่ยง แต่สัมพันธ์กับการติดเชื้อที่น้อยลง (protective factor) และความสัมพันธ์มีนัยสำคัญทางสถิติ (χ² = 7.84, p = 0.005) ข้อมูลเป็นความชุก จึงคำนวณ prevalence ratio แทนได้เช่นกัน",
    "explain": "**หลัก** การประเมินว่าปัจจัยหนึ่งเป็นปัจจัยเสี่ยงหรือไม่ใช้ค่าวัดความสัมพันธ์แบบอัตราส่วน ซึ่งมีค่าว่าง (null value) เท่ากับ 1 ค่ามากกว่า 1 คือเพิ่มโอกาสเกิดโรค ค่าน้อยกว่า 1 คือลดโอกาส\n**แทนค่า** ข้อมูลแบ่งฝูงเป็นติดเชื้อและไม่ติดเชื้อ จึงคำนวณ OR = ad/bc ได้เท่ากับ (14×20)/(18×57) = 0.273\n**แปลผล** การมีแมวสัมพันธ์กับ odds ของการติดเชื้อที่ต่ำลง\n\n**ข้อควรระวัง**\n— จุดที่พลาดง่ายคือการเขียนว่าโอกาสเกิดโรคลดลง 0.273 เท่า ความหมายที่ถูกคือ odds ในฝูงที่มีแมวเป็น 0.273 เท่าของ odds ในฝูงที่ไม่มีแมว\n— OR บอกความสัมพันธ์ ยังไม่ได้พิสูจน์ว่าแมวเป็นสาเหตุที่ทำให้ติดเชื้อน้อยลง",
    "explainSay": "การประเมินว่าปัจจัยหนึ่งเป็นปัจจัยเสี่ยงหรือไม่ใช้ค่าวัดความสัมพันธ์แบบอัตราส่วน ซึ่งมีค่าว่าง (null value) เท่ากับ 1 ค่ามากกว่า 1 คือเพิ่มโอกาสเกิดโรค ค่าน้อยกว่า 1 คือลดโอกาส ข้อมูลแบ่งฝูงเป็นติดเชื้อและไม่ติดเชื้อ จึงคำนวณ OR = ad/bc ได้เท่ากับ (14×20)/(18×57) = 0.273 การมีแมวสัมพันธ์กับ odds ของการติดเชื้อที่ต่ำลง จุดที่พลาดง่ายคือการเขียนว่าโอกาสเกิดโรคลดลง 0.273 เท่า ความหมายที่ถูกคือ odds ในฝูงที่มีแมวเป็น 0.273 เท่าของ odds ในฝูงที่ไม่มีแมว และ OR บอกความสัมพันธ์ ยังไม่ได้พิสูจน์ว่าแมวเป็นสาเหตุที่ทำให้ติดเชื้อน้อยลง",
