    "explain": "ระยะฟักตัว (incubation period) คือช่วงตั้งแต่สัตว์สัมผัสเชื้อจนเริ่มแสดงอาการทางคลินิกครั้งแรก ระยะแฝง (latent period) วัดจากการสัมผัสเชื้อจนสัตว์เริ่มแพร่เชื้อให้ตัวอื่นได้ จึงไม่ได้สิ้นสุดที่การแสดงอาการ และสัตว์มักแพร่เชื้อได้ก่อนป่วยให้เห็น Period of communicability คือช่วงที่สัตว์แพร่เชื้อได้ (infectious period) ซึ่งบางโรคต่อเนื่องไปหลังหายป่วย ส่วน induction period ไม่ใช่หนึ่งในสามช่วงเวลาที่ใช้อธิบายธรรมชาติของโรคติดเชื้อ (incubation, latent และ infectious period)",
