    "answer": 2,
    "explain": "ไข้หวัดนกเป็นโรคติดต่อที่แพร่จากสัตว์ปีกที่ติดเชื้อไปสู่ตัวอื่นและฝูงอื่น ผ่านการสัมผัส การเคลื่อนย้ายสัตว์ปีก ยานพาหนะ อุปกรณ์ และนกในธรรมชาติ ผู้ป่วยรายใหม่จึงเกิดต่อเนื่องเป็นรุ่น ๆ จากผู้ป่วยรุ่นก่อน ซึ่งเป็นลักษณะของ propagated epidemic เช่นเดียวกับการแพร่ของ FMD ระหว่างฟาร์มที่ควบคุมไม่ได้ ส่วน common source epidemic ทั้งสามแบบหมายถึงทุกรายได้รับเชื้อจากแหล่งเดียวกัน ต่างกันที่ลักษณะการสัมผัส: point คือสัมผัสครั้งเดียวในช่วงสั้น intermittent คือสัมผัสเป็นครั้งคราวไม่สม่ำเสมอ และ continuous คือสัมผัสแหล่งเดียวกันต่อเนื่องเป็นเวลานาน การระบาดที่กินเวลานานจึงไม่ใช่ continuous source ถ้าเชื้อแพร่จากสัตว์ป่วยไปยังตัวอื่นต่อเป็นทอด ๆ",
