    "q": "ความแตกต่างระหว่างสัดส่วนของสุนัขที่กินอาหาร dry ในกลุ่ม case และกลุ่ม control สามารถใช้สถิติทดสอบอะไร",
    "options": [
      "Student's t-test",
      "One-way Analysis of Variance",
      "Chi-square test",
      "Pearson's correlation"
    ],
    "answer": 2,
    "explain": "การกินอาหาร dry (กินหรือไม่กิน) และการเป็น case หรือ control เป็นตัวแปรเชิงกลุ่มทั้งคู่ การเปรียบเทียบสัดส่วนระหว่างสองกลุ่มจึงจัดเป็นตาราง 2×2 แล้วทดสอบความสัมพันธ์ด้วย chi-square test (ถ้าค่าคาดหวังในช่องใดน้อยกว่า 5 มักใช้ Fisher's exact test แทน) Student's t-test เปรียบเทียบค่าเฉลี่ยของตัวแปรต่อเนื่อง ทั้งค่าเฉลี่ยของตัวอย่างเดียวกับค่าอ้างอิงและค่าเฉลี่ยระหว่างสองกลุ่ม one-way analysis of variance เปรียบเทียบค่าเฉลี่ยของสามกลุ่มขึ้นไป และ Pearson's correlation วัดความสัมพันธ์ระหว่างตัวแปรต่อเนื่องสองตัว ทั้งสามจึงไม่ใช่การทดสอบสัดส่วน",
