    "passage": "งานวิจัยชิ้นนี้ต้องการศึกษาความสัมพันธ์ระหว่าง factor ต่าง ๆ กับการเกิดนิ่วชนิด struvite ในสุนัข เป็นการศึกษาแบบ case-control study โดยกลุ่ม case คือ สุนัขที่เป็นนิ่วชนิด struvite และกลุ่ม control เป็นสุนัขที่มารับการรักษาในโรงพยาบาล ทำการวิเคราะห์โดยวิธี logistic regression แบบหลายตัวแปร (Okafor et al., 2013) ได้ผลดังนี้\n\n| ตัวแปรและกลุ่มที่เปรียบเทียบ | จำนวนสุนัขกลุ่ม case | จำนวนสุนัขกลุ่ม control (general controls) | OR (95% CI) |\n|---|---|---|---|\n| Diet, dry vs nondry | 196 | 1,404 | 0.89 (0.57-1.38) |\n| Sex, female vs male | 508 | 3,668 | 12.63 (9.02-17.69) |\n| Neutered, yes vs no | 508 | 3,668 | 7.39 (5.35-10.20) |\n| Breed size category, all | 507 | 3,668 | ไม่มีค่า OR |\n| Breed size category, large vs medium | 118 | 1,832 | 0.43 (0.28-0.66) |\n| Breed size category, small vs medium | 267 | 1,685 | 3.15 (2.40-4.13) |\n| Breed size category, toy vs medium | 389 | 2,207 | 2.06 (1.58-2.67) |\n| Body condition, all | 149 | 545 | ไม่มีค่า OR |\n| Body condition, thin vs normal | 8 | 86 | 0.22 (0.04-1.14) |\n| Body condition, heavy vs normal | 147 | 493 | 1.74 (0.72-4.23) |\n| Weight (kg), 1 kg increase | 508 | 3,668 | 0.97 (0.96-0.98) |\n| Age (y), 1 y increase | 508 | 3,668 | 2.85 (2.50-3.24) |\n| Age² (y²), 1 y² increase | 508 | 3,668 | 0.92 (0.91-0.93) |\n| No. of cats in household, 1 unit increase | 508 | 3,668 | 0.90 (0.90-1.06) |\n| No. of dogs in household, 1 unit increase | 508 | 3,668 | 0.99 (0.96-1.02) |",
    "passage_title": "ปัจจัยที่สัมพันธ์กับนิ่วชนิด struvite ในสุนัข (case-control)"
