    "year": 5,
    "type": "short",
    "examScope": "final",
    "q": "ในการตรวจวินิจฉัยโรคพิษสุนัขบ้า ถ้าผลการตรวจเป็นผลบวกลวง (false positive) หรือผลลบลวง (false negative) จะเกิดผลอะไรขึ้นในโรงพยาบาล",
    "keywords": [
      "ผลบวกลวง = 1 - specificity",
      "ผลลบลวง = 1 - sensitivity",
      "ใช้มาตรการควบคุมโรคโดยไม่จำเป็น",
      "ผู้สัมผัสไม่ได้รับการป้องกัน",
      "แพร่เชื้อต่อ",
      "ไม่ถูกรายงาน",
      "rule-out ใช้ sensitivity สูง"
    ],
    "model_answer": "ผลบวกลวง (false positive) คือสัตว์ที่ไม่ได้เป็นโรคพิษสุนัขบ้าแต่ตรวจได้ผลบวก สัดส่วนเท่ากับ 1 - specificity ผลที่ตามมาคือคนและสัตว์ที่สัมผัสสัตว์ตัวนั้นถูกจัดการเหมือนสัมผัสโรค เช่น สัตว์ร่วมบ้านหรือร่วมฝูงถูกกักและควบคุมการเคลื่อนย้าย มีการสอบสวนโรค ฉีดวัคซีนรอบจุดเกิดโรค และประกาศเตือนภัยโดยไม่จำเป็น เสียค่าใช้จ่ายและสร้างความตื่นตระหนก ผลลบลวง (false negative) คือสัตว์ที่เป็นโรคแต่ตรวจได้ผลลบ สัดส่วนเท่ากับ 1 - sensitivity ผลที่ตามมาคือพลาดผู้ป่วย เจ้าหน้าที่ เจ้าของ และผู้ที่ถูกกัดไม่ได้รับการป้องกันที่จำเป็นและเสี่ยงต่อการติดเชื้อ สัตว์ที่สัมผัสโรคไม่ถูกกัก โรคแพร่ต่อและไม่ถูกรายงาน สำหรับโรคพิษสุนัขบ้า ผลลบลวงอันตรายกว่า การตรวจเพื่อตัดโรคออก (rule-out) จึงควรใช้วิธีที่ sensitivity สูง และยืนยันผลบวก (rule-in) ด้วยวิธีที่ specificity สูง",
    "explain": "ความผิดพลาดสองชนิดเกิดจากคุณสมบัติคนละตัวของการตรวจ ผลบวกลวงเกิดในสัตว์ที่ไม่เป็นโรค สัดส่วนเท่ากับ 1 - specificity ผลลบลวงเกิดในสัตว์ที่เป็นโรค สัดส่วนเท่ากับ 1 - sensitivity ผลที่ตามมาจึงต่างกัน ผลบวกลวงทำให้ดำเนินการกับคนและสัตว์ที่สัมผัสโดยไม่จำเป็น ผลลบลวงทำให้ผู้สัมผัสโรคไม่ได้รับการป้องกันและโรคแพร่ต่อ โรคพิษสุนัขบ้าติดต่อสู่คน การพลาดผู้ป่วยจึงมีราคาแพงกว่า ความไวสูงทำให้ผลลบลวงน้อยและค่าพยากรณ์ผลลบ (NPV) สูง ส่วนความจำเพาะสูงทำให้ผลบวกลวงน้อยและค่าพยากรณ์ผลบวก (PPV) สูง",
