    "id": 213564,
    "subject": "epidemiology",
    "topic": "epidem-control-prevention",
    "year": 5,
    "type": "short",
    "q": "จงบอกปัจจัย 4 ด้านที่ต้องพิจารณาในการกำหนดเป้าหมายที่บรรลุได้ของโปรแกรมควบคุมโรค (disease control programme) และยกตัวอย่างประกอบ 1 ตัวอย่าง",
    "keywords": [
      "Biological factors",
      "Availability of technical tools",
      "Control measures",
      "Socioeconomic considerations",
      "species affected",
      "zoonotic potential",
      "vaccines",
      "cost and benefits"
    ],
    "model_answer": "ปัจจัย 4 ด้าน (factors to consider in setting achievable goals for a disease control programme) 1) Biological factors: ชนิดสัตว์ที่ติดเชื้อ ความสามารถติดต่อสู่คน ความคงที่และความหลากหลายทางพันธุกรรมของเชื้อ การกระจายและความหนาแน่นของสัตว์ไวรับ แหล่งรังโรคในสัตว์ป่า วิธีการแพร่ (เช่น ผ่านพาหะ) ความสามารถในการแพร่ ขอบเขตของโรคในปัจจุบัน ความทนของเชื้อในสิ่งแวดล้อม และภาวะตัวพาเชื้อ 2) Availability of technical tools: ชุดตรวจวินิจฉัย วัคซีน การรักษา ยาฆ่าเชื้อและยาฆ่าแมลง สถานที่และวิธีทำลายซาก และบุคลากรที่ได้รับการฝึก 3) Control measures: ควบคุมการเคลื่อนย้าย stamping out หรือการฆ่าสัตว์ จำกัดการนำเข้าส่งออก zoning หรือ compartmentalisation การรับรองฝูง แยกกักและกักกัน ทำความสะอาดและฆ่าเชื้อ ควบคุมพาหะและแหล่งรังโรค จัดการผลิตภัณฑ์และผลพลอยได้ และการฉีดวัคซีน 4) Socioeconomic considerations: ต้นทุนและผลประโยชน์ของมาตรการ ทรัพยากรที่มี โครงสร้างระบบการผลิตปศุสัตว์ ผลกระทบต่อสาธารณสุข ความยากง่ายในการปฏิบัติ การมีส่วนร่วมของผู้มีส่วนได้ส่วนเสีย ผลกระทบต่อสิ่งแวดล้อม เจตจำนงทางการเมือง แรงจูงใจและค่าชดเชย การยอมรับของสาธารณะ สินค้าที่ปลอดภัยต่อการค้า การบริหารและการแบ่งบทบาท และงบประมาณ ตัวอย่าง โรคไข้หวัดนก (HPAI): ด้านชีวภาพ เป็นโรคติดต่อสู่คนและมีนกอพยพเป็นแหล่งนำโรค ด้านเครื่องมือ ต้องมีวิธีตรวจทางห้องปฏิบัติการ อุปกรณ์ทำลายสัตว์ปีก และทีมทำลายสัตว์ปีกที่ฝึกแล้ว ด้านมาตรการ ทำลายสัตว์ปีก ณ จุดพบโรคภายใน 12 ชั่วโมง ควบคุมการเคลื่อนย้ายสัตว์ปีกในรัศมี 10 กิโลเมตรอย่างน้อย 30 วัน และเฝ้าระวังโรค ด้านเศรษฐกิจและสังคม โรคกระทบเศรษฐกิจและการส่งออกอย่างมาก ต้องมีงบประมาณจ่ายค่าชดเชยและประชาสัมพันธ์ให้เกษตรกรเข้าใจ",
    "explain": "การตั้งเป้าหมายของโปรแกรมควบคุมโรคให้บรรลุได้จริงต้องประเมินสี่ด้านพร้อมกัน ลักษณะทางชีวภาพของโรคบอกว่าควบคุมยากง่ายเพียงใด เช่น โรคที่มีแหล่งรังโรคในสัตว์ป่าหรือมีภาวะตัวพาเชื้อกำจัดได้ยาก เครื่องมือทางเทคนิคบอกว่าทำได้หรือไม่ เช่น มีชุดตรวจ วัคซีน และบุคลากรพอหรือไม่ มาตรการควบคุมคือสิ่งที่จะลงมือทำ และปัจจัยทางเศรษฐกิจและสังคมบอกว่าคุ้มค่าและได้รับการยอมรับหรือไม่ การนำโรคหนึ่งโรคมาวิเคราะห์ตามกรอบสี่ด้านนี้จะได้โครงร่างของโปรแกรมควบคุมโรคนั้น",
    "source": "10 - Control_Prevention_Eradication_Epi2024 deck 2024 หน้า 8; 7. Disease Control, Prevention and Eradication (การควบคุม ป้องกัน และกำจัดโรค) หน้า 26, 36, 38, 41 และ 47; Concept of disease transmission_TC 3 August 2026 หน้า 9",
    "verified": "หน้ารวมคำบอกเล่าข้อสอบแต่ละส่วน กล่องบนซ้าย ส่วนข้อเขียนการควบคุมโรค พร้อมบันทึกปากกาน้ำเงินระบุปัจจัย 4 ด้าน: ไฟล์ epidem midterm ในชุดไฟล์ Vet 84 หน้า 2; หน้าเดียวกันที่ไม่มีบันทึกปากกาน้ำเงิน: ไฟล์ key mid 5.1 ในชุดไฟล์ Vet 84 หน้า 1",
